INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann eine GbR von einer Einzelperson gegründet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Mindestens zwei Gesellschafter nötig"}, {"text": "Ja", "correct": false, "because": "Partnerschaft erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine GbR ins Handelsregister eingetragen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Keine Handelsgesellschaft"}, {"text": "Ja", "correct": false, "because": "Nur bei Handelsgewerbe nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Haftung in einer GbR für alle Gesellschafter gleich?', 2, '[{"text": "Ja", "correct": true, "because": "Alle haften unbeschränkt"}, {"text": "Nein", "correct": false, "because": "Einheitliche Haftungsstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte eine GbR in der IT-Branche typisch sein?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel für Dienstleistungen"}, {"text": "Nein", "correct": false, "because": "Nicht branchenspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Ist die Gründung einer GbR teuer?', 2, '[{"text": "Nein", "correct": true, "because": "Kein Mindestkapital nötig"}, {"text": "Ja", "correct": false, "because": "Kostengünstig möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine GbR ohne schriftlichen Vertrag existieren?', 2, '[{"text": "Ja", "correct": true, "because": "Formfreiheit BGB"}, {"text": "Nein", "correct": false, "because": "Vertrag nicht zwingend schriftlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Vorteil der GbR die begrenzte Haftung?', 2, '[{"text": "Nein", "correct": true, "because": "Unbeschränkte Haftung"}, {"text": "Ja", "correct": false, "because": "Nachteil der GbR"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine GbR Steuern zahlen?', 2, '[{"text": "Ja", "correct": true, "because": "Gewerbesteuer bei Handelsgewerbe"}, {"text": "Nein", "correct": false, "because": "Steuerpflicht je nach Tätigkeit"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil einer GbR?', 2, '[{"text": "Einfache Gründung", "correct": true, "because": "Wenig Formalitäten"}, {"text": "Begrenzte Haftung", "correct": false, "because": "Nachteil"}, {"text": "Hohe Kosten", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin plant eine GbR. Was ist ein Nachteil?', 3, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Risiko für Gesellschafter"}, {"text": "Einfache Struktur", "correct": false, "because": "Vorteil"}, {"text": "Flexibilität", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branche ist für eine GbR typisch?', 2, '[{"text": "Freie Berufe", "correct": true, "because": "Ärzte, Anwälte häufig"}, {"text": "Nur Produktion", "correct": false, "because": "Nicht ausschließlich"}, {"text": "Nur Handel", "correct": false, "because": "Nicht beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, wie eine GbR gegründet wird. Was sage ich?', 3, '[{"text": "Durch Gesellschaftsvertrag", "correct": true, "because": "Gründungsprozess BGB"}, {"text": "Durch Handelsregister", "correct": false, "because": "Nicht zwingend"}, {"text": "Durch Kapital", "correct": false, "because": "Kein Mindestkapital"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat eine GbR?', 4, '[{"text": "Einfache Gründung", "correct": true, "because": "Wenig Formalitäten"}, {"text": "Geringe Kosten", "correct": true, "because": "Kein Mindestkapital"}, {"text": "Flexibilität", "correct": true, "because": "Anpassungsfähig"}, {"text": "Begrenzte Haftung", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine GbR?', 3, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Persönliches Risiko"}, {"text": "Keine Rechtspersönlichkeit", "correct": true, "because": "Keine eigene Identität"}, {"text": "Gemeinsame Entscheidungen", "correct": true, "because": "Abstimmungsaufwand"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Anforderungen gelten für eine GbR?', 3, '[{"text": "Gesellschaftsvertrag", "correct": true, "because": "BGB §705"}, {"text": "Mindestens zwei Gesellschafter", "correct": true, "because": "Partnerschaft"}, {"text": "Gewerbeanmeldung bei Handel", "correct": true, "because": "Gewerberecht"}, {"text": "Handelsregistereintrag", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kennzeichnet die Haftungsstruktur einer GbR?', 4, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "BGB §721"}, {"text": "Persönliche Haftung", "correct": true, "because": "Gesellschaftervermögen"}, {"text": "Solidarische Haftung", "correct": true, "because": "Gemeinsam"}, {"text": "Begrenzte Haftung", "correct": false, "because": "Nicht gegeben"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die GbR hat eine einfache Gründung. b) Sie bietet begrenzte Haftung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gründung ja, Haftung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Alle haften unbeschränkt in der GbR. b) Ein Handelsregistereintrag ist Pflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, Eintrag nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die GbR ist für Freie Berufe typisch. b) Sie erfordert hohes Startkapital.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Berufe ja, Kapital nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die GbR braucht einen Vertrag. b) Sie ist nur für Handel geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertrag ja, Handel nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

